    def is_num(v):
        return isinstance(v, (int, float))

    def pair(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1])

    def get(o, k, d=None):
        try:
            return o.get(k, d)
        except Exception:
            return d

    def xy(v):
        if isinstance(v, dict):
            x = v.get("x", v.get("col", v.get("cx")))
            y = v.get("y", v.get("row", v.get("cy")))
            if is_num(x) and is_num(y):
                return [x, y]
        if pair(v):
            return [v[0], v[1]]
        return None

    def find_first_pos(obj):
        if isinstance(obj, dict):
            for k in ("position", "pos", "loc", "location", "agent_position", "self_pos", "self_position"):
                p = xy(obj.get(k))
                if p is not None:
                    return p
            for v in obj.values():
                p = find_first_pos(v)
                if p is not None:
                    return p
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                p = find_first_pos(v)
                if p is not None:
                    return p
        return None

    def collect_positions(obj, keys):
        out = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                ks = str(k).lower()
                if any(t in ks for t in keys):
                    if isinstance(v, dict):
                        p = xy(v)
                        if p is not None:
                            out.append(p)
                        else:
                            for vv in v.values():
                                p = xy(vv)
                                if p is not None:
