                            if p is not None:
                                out.append(p)
                    else:
                        p = xy(v)
                        if p is not None:
                            out.append(p)
            if not out:
                for v in obj.values():
                    out.extend(collect_positions(v, keys))
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                out.extend(collect_positions(v, keys))
        return out

