    if me is None:
        return [0, 0]

    targets = []
    threats = []
    friends = []

    target_keys = ("resource", "food", "goal", "target", "objective", "point", "base", "flag", "capture", "territ")
    threat_keys = ("enemy", "opponent", "threat", "hazard", "projectile", "predator")
    friend_keys = ("ally", "teammate", "friend")

    for src in (observation, get(observation, "world"), get(observation, "game"), get(observation, "state")):
